#!/usr/bin/env node
// SPDX-License-Identifier: GPL-3.0-only
// Generates merge-group constants for both clients from packages/contracts/schema/*.json:
//   apps/android/core/model/src/main/kotlin/dev/zwallet/core/model/contracts/Contracts.kt
//   apps/web/src/generated/contracts.ts
// Usage: node scripts/codegen.mjs [--check]   (--check fails if a generated file is stale)

import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { loadContracts } from '../lib/contracts.mjs';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../..');
const KOTLIN_OUT = path.join(
  ROOT,
  'apps/android/core/model/src/main/kotlin/dev/zwallet/core/model/contracts/Contracts.kt',
);
const TS_OUT = path.join(ROOT, 'apps/web/src/generated/contracts.ts');

const HEADER = (comment) =>
  [
    `${comment} SPDX-License-Identifier: GPL-3.0-only`,
    `${comment} GENERATED by packages/contracts/scripts/codegen.mjs from packages/contracts/schema/*.json.`,
    `${comment} Do not edit. Regenerate with: pnpm --filter @zwallet/contracts codegen`,
  ].join('\n');

const camel = (s) => s.replace(/_([a-z])/g, (_, c) => c.toUpperCase());
const pascal = (s) => camel(s).replace(/^./, (c) => c.toUpperCase());
const kStr = (s) => JSON.stringify(s);

function kotlin({ schemaVersion, formatVersion, tables }) {
  const list = (items, indent) =>
    items.length === 0
      ? 'emptyList()'
      : `listOf(\n${items.map((c) => `${indent}    ${kStr(c)},`).join('\n')}\n${indent})`;
  const spec = (t) => {
    const ind = ' '.repeat(20);
    const groups = Object.entries(t.groups)
      .map(([g, cols]) => {
        const oneLine = `${ind}${kStr(g)} to listOf(${cols.map(kStr).join(', ')}),`;
        if (oneLine.length <= 120) return oneLine;
        return `${ind}${kStr(g)} to\n${ind}    ${list(cols, `${ind}    `)},`;
      })
      .join('\n');
    return [
      `    val ${camel(t.name)}: TableSpec =`,
      `        TableSpec(`,
      `            name = ${kStr(t.name)},`,
      `            columns =
                ${list(t.columns, '                ')},`,
      t.immutable.length
        ? `            immutable =
                ${list(t.immutable, '                ')},`
        : `            immutable = emptyList(),`,
      `            groups =`,
      `                linkedMapOf(`,
      groups,
      `                ),`,
      `        )`,
    ].join('\n');
  };
  return `${HEADER('//')}
package dev.zwallet.core.model.contracts

/**
 * Merge metadata for one user-data table (ADR 0009). Every column is either in [meta],
 * in [immutable], or in exactly one merge group.
 */
class TableSpec(
    val name: String,
    /** Every column, in schema order. */
    val columns: List<String>,
    /** Set once at creation and never merged: equal on every copy by construction. */
    val immutable: List<String>,
    /** Merge group name → its columns, in declaration order. */
    val groups: Map<String, List<String>>,
) {
    /** Column → the merge group that owns it. */
    val groupOf: Map<String, String> =
        groups.flatMap { (group, cols) -> cols.map { it to group } }.toMap()

    companion object {
        /** Bookkeeping columns every table has; merged by rule, not by group. */
        val meta: List<String> = listOf("id", "hlc", "field_hlc", "created_at", "updated_at")
    }
}

object Contracts {
    const val SCHEMA_VERSION: Int = ${schemaVersion}
    const val FORMAT_VERSION: Int = ${formatVersion}

${tables.map(spec).join('\n\n')}

    /** Every user-data table in foreign-key order (parents first). */
    val tables: List<TableSpec> =
        listOf(
${tables.map((t) => `            ${camel(t.name)},`).join('\n')}
        )

    private val byName: Map<String, TableSpec> = tables.associateBy { it.name }

    fun table(name: String): TableSpec = byName[name] ?: throw IllegalArgumentException("Unknown table: $name")
}
`;
}

function tsType(prop) {
  const types = Array.isArray(prop.type) ? prop.type : [prop.type];
  const nullable = types.includes('null');
  let base;
  if (prop.const !== undefined) base = JSON.stringify(prop.const);
  else if (prop.enum) base = prop.enum.filter((v) => v !== null).map((v) => JSON.stringify(v)).join(' | ');
  else base = types.includes('integer') ? 'number' : 'string';
  return nullable ? `${base} | null` : base;
}

function typescript({ schemaVersion, formatVersion, tables }) {
  const arr = (items) => `[${items.map((s) => JSON.stringify(s)).join(', ')}]`;
  const specs = tables
    .map(
      (t) => `  ${t.name}: {
    name: ${JSON.stringify(t.name)},
    columns: ${arr(t.columns)},
    immutable: ${arr(t.immutable)},
    groups: {
${Object.entries(t.groups)
  .map(([g, cols]) => `      ${g}: ${arr(cols)},`)
  .join('\n')}
    },
  },`,
    )
    .join('\n');
  const rows = tables
    .map(
      (t) => `/** A \`${t.name}\` row. Integer columns ending in \`_minor\` are money in minor units. */
export interface ${pascal(t.name)}Row {
${t.columns.map((c) => `  ${c}: ${tsType(t.properties[c])};`).join('\n')}
}`,
    )
    .join('\n\n');
  return `${HEADER('//')}

export const SCHEMA_VERSION = ${schemaVersion};
export const FORMAT_VERSION = ${formatVersion};

/** Merge metadata for one user-data table (ADR 0009). */
export interface TableSpec {
  readonly name: string;
  /** Every column, in schema order. */
  readonly columns: readonly string[];
  /** Set once at creation and never merged: equal on every copy by construction. */
  readonly immutable: readonly string[];
  /** Merge group name → its columns. */
  readonly groups: Readonly<Record<string, readonly string[]>>;
}

/** Bookkeeping columns every table has; merged by rule, not by group. */
export const META_COLUMNS = ['id', 'hlc', 'field_hlc', 'created_at', 'updated_at'] as const;

export const TABLES = {
${specs}
} as const satisfies Record<string, TableSpec>;

export type TableName = keyof typeof TABLES;

/** Every user-data table in foreign-key order (parents first). */
export const TABLE_ORDER: readonly TableName[] = ${arr(tables.map((t) => t.name))};

${rows}

export interface Rows {
${tables.map((t) => `  ${t.name}: ${pascal(t.name)}Row;`).join('\n')}
}
`;
}

const contracts = loadContracts();
const outputs = [
  [KOTLIN_OUT, kotlin(contracts)],
  [TS_OUT, typescript(contracts)],
];

const check = process.argv.includes('--check');
let stale = 0;
for (const [file, content] of outputs) {
  const rel = path.relative(ROOT, file);
  if (check) {
    const current = existsSync(file) ? readFileSync(file, 'utf8').replace(/\r\n/g, '\n') : null;
    if (current !== content) {
      console.error(`stale: ${rel}`);
      stale++;
    } else console.log(`up to date: ${rel}`);
  } else {
    mkdirSync(path.dirname(file), { recursive: true });
    writeFileSync(file, content);
    console.log(`wrote ${rel}`);
  }
}
if (stale) {
  console.error('Generated contracts are stale. Run: pnpm --filter @zwallet/contracts codegen');
  process.exit(1);
}
